"""Writes report.md for the 2026-11-11 low-impedance divider (DF-3 only) from results/*.json."""
import os, json
HERE = os.path.dirname(os.path.abspath(__file__))
import dlib
RES = os.path.join(HERE, "results") if dlib.VARIANT == "hz" else os.path.join(HERE, "results", dlib.VARIANT)

def write():
    S = json.load(open(os.path.join(RES, "scenario_lowz.json")))
    H = json.load(open(os.path.join(RES, "header.json")))
    G = json.load(open(os.path.join(RES, "guards_lowz.json")))
    nom = H["nom"]
    L = []; A = L.append
    if dlib.VARIANT == "hz":
        A("# 2d differential mode, DF-3 for the 1 Mohm compensated divider (2026-11-11 pivot)\n")
        A("Regenerated by `python3 -I run.py` (variant `hz`, the default; D2_WORKERS ngspice processes, default 4). Route (c) (the ~20 kohm divider) is `report_round1.md` / `results/lowz/` and `report_lowz2.md` / `results/lowz2/`; the first 1 Mohm round is `report_legacy.md`.\n")
        A(f"- Simulator `{H['ngspice']}`; OPA354 model sha256 `{H['opa354_lib_sha256']}`; range-switch model sha256 `{H['rangesw_sha256']}`. The channel netlist is 2b's (`../scope/netlib.py`, variant `hz`): R1 = R3 = {nom['R1']/1e3:.0f}k (330k + 330k + 100k), R2 {nom['R2']/1e3:.0f}k fixed, C1 12 pF, C2 20 || (12 s 39) = 29.2 pF with the T-switch's CSOFF 6 pF at N, Rnp 680, RF 953 / RG 249 with the range switch across RF, per-channel Vmid (P8-k stand-in), the shared 249 ohm + 10 uF sense filter.")
        A(f"- Every resistor **0.1 % at 25 ppm/K**, capacitors +/-5 %, stray +/-0.5 pF per channel, no trimmer, Ron 3.7-8.8 ohm independent per channel, dT = +/-{H['dT']:.0f} K, {H['nmc']} Monte Carlo draws (seed {H['seed']}) and six signed corners. **Sources matched (owner, 2026-11-11): both <= 100 ohm and within 10 ohm**: draws take Rsb within +/-10 ohm of Rsa; corners 0/10, 10/0 and 90/100 ohm.")
        A(f"- Calibration (PA-3): DAC0 buffer + 249 ohm through the T-switch onto N, the MCP3564 reading the source side (at a 180 kohm Thevenin the switch's Ron divides by about 20 ppm): the host fits each channel's stage gain and does not see the divider; residual **{H['cal_res']['5']*1e6:.0f} / {H['cal_res']['1.25']*1e6:.0f} ppm** per channel, opposite signs.\n")
    else:
        A("# 2d differential mode, DF-3 for the low-impedance divider, round 2 (2026-11-11)\n")
        A("Round 2: R3 returns to the shared sense buffer through the R3-leg injection switch; Kelvin range switch (Ron in no gain); the calibration reads N directly with the MCP3564 (powercal), so it measures each channel's stage and not the divider ('after calibration' rows). **DF-3 is judged for matched sources (owner, 2026-11-11): both <= 100 ohm and within 10 ohm of each other**: the Monte Carlo draws Rsb within +/-10 ohm of Rsa, the corners use 0/10, 10/0 and 90/100 ohm. Round 1 is `report_round1.md`, `results/lowz/`.\n")
        A("Regenerated by `python3 -I run.py` (D2_WORKERS ngspice processes, default 4; about 15 minutes at 4). The superseded 1 Mohm design's full 2d report is `report_legacy.md` (`D2_VARIANT=legacy python3 -I run.py`, results in `results/legacy/`).\n")
        A(f"- Simulator `{H['ngspice']}`; OPA354 model sha256 `{H['opa354_lib_sha256']}`; range-switch model sha256 `{H['rangesw_sha256']}`. The channel netlist is 2b's (`../scope/netlib.py`, variant `lowz`).")
        A(f"- Divider: R1 {nom['R1']:.1f} ohm (6 x 100k || + 249), R2 {nom['R2']:.1f} ohm ((8 x 953) || 330k), R3 {nom['R3']:.1f} ohm (6 x 100k ||) + Rs3 {nom['Rs3']:.0f} ohm (the channel's own sense filter), RF 953 / RG 249; every resistor **0.1 % at 25 ppm/K** (the 100k and 249 types are 10 ppm/K; 25 is used for all, as instructed), no trimmer, Ron 3.7-8.8 ohm independent per channel, dT = +/-{H['dT']:.0f} K, {H['nmc']} Monte Carlo draws (seed {H['seed']}) and five signed corners, sources matched (see above).")
        A(f"- Calibration (PA-3): the host fits each channel's stage gain from DAC0 injected at node N; residual **{H['cal_res']['5']*1e6:.0f} ppm (+/-5 V) / {H['cal_res']['1.25']*1e6:.0f} ppm (+/-1.25 V)** per channel with opposite signs (the worse of both). Two further rows: (a) the same plus the injection's own error at a ~4 kohm node, N = DAC0 x (1 - Ron/(Rth + Ron)), with Ron 3.7-8.8 ohm unknown per unit and corrected with the mid value 6.25 ohm (residual up to +/-{2.55/3962*1e6:.0f} ppm, *(derived)*); (b) the proposal of 2b's report, the injection switch in the R3 leg, which reads the channel through R3 instead of after the divider.\n")
    A("| row | range | limit | worst signed corner | Monte Carlo min / 1st pct / median | verdict | margin at the corner |")
    A("|---|---|---|---|---|---|---|")
    for rg, nm in (("5", "+/-5 V"), ("1.25", "+/-1.25 V")):
        d = S["summary"][rg]
        A(f"| DF-3 before calibration, DC | {nm} | >= 30 dB | {d['dc_corner_min']:.1f} dB | {d['dc_mc_min']:.1f} / - / {d['dc_mc_med']:.1f} | {'PASS' if min(d['dc_corner_min'], d['dc_mc_min']) >= 30 else 'FAIL'} | {d['dc_corner_min']-30:+.1f} dB |")
        A(f"| DF-3 before calibration, 10 kHz | {nm} | >= 18 dB | {d['f10k_wc']:.1f} dB | {d['f10k_mc_min']:.1f} / {d['f10k_mc_p1']:.1f} / - | {'PASS' if min(d['f10k_wc'], d['f10k_mc_min']) >= 18 else 'FAIL'} | {d['f10k_wc']-18:+.1f} dB |")
        for k, lab in (("res", "after calibration, residual 55/62 ppm"), ("dc", "after calibration, exact (no residual), reference"),
                       ("r3", "after calibration, if it read the DAC0 source instead (sees the divider through R3)")):
            if k not in S["cal"][rg]:
                continue
            c = S["cal"][rg][k]
            A(f"| DF-3 {lab} | {nm} | >= 44 dB | {c['corner_min']:.1f} dB | {c['mc_min']:.1f} / {c['mc_p1']:.1f} / {c['mc_med']:.1f} | {'PASS' if min(c['corner_min'], c['mc_min']) >= 44 else 'FAIL'} | {c['corner_min']-44:+.1f} dB |")
    A("")
    n_bad = sum(S["cal"][rg][k]["mc_below_corner"] for rg in ("5", "1.25") for k in S["cal"][rg])
    A(f"Monte Carlo draws below their row's signed corner: {n_bad} (must be 0: the corners bound the draws).\n")
    A("**What sets the worst corner** (after calibration, 55/62 ppm residual, worst of the hot and cold corners, one term changed at a time):\n")
    A("| case | +/-5 V | +/-1.25 V |\n|---|---|---|")
    for lab, v in S["variants"].items():
        A(f"| {lab} | {v['5']:.1f} dB | {v['1.25']:.1f} dB |")
    A("\nA source asymmetry dRs is a gain error of about (1 - alpha) x dRs / R1 on one channel, which no calibration of the AFE sees: 0.047 % per 10 ohm. Equal sources cancel except through the second-order change of alpha with Rs. The divider's own tolerance and drift give about 2 x 1.54 x (0.1 % + 25 ppm/K x 10 K) = 0.39 % at the corner, the op-amp CMRR term 0.08 %.\n")
    A("## Guards (each check broken on purpose)\n")
    A("| check | mutation | good | broken | restored | effective |\n|---|---|---|---|---|---|")
    for g in G:
        A(f"| {g['guard']} | {g['mutation']} | {g['good']:.1f} dB | {g['broken']:.1f} dB | {g['restored']:.1f} dB | {'yes' if g['effective'] else 'NO'} |")
    A("")
    A("## Assumptions *(check)*\n")
    A("- The calibration residual 55/62 ppm is the 2026-11-11 what-if's MCP3564 figure (`whatif/results-2026-11-11.md`, section D; its scripts were lost); not re-derived here.")
    A("- The injection switch's Ron is unknown per unit within 3.7-8.8 ohm (TMUX1119 typ/max at 3.3 V); no minimum is given.")
    A("- Op-amp CMRR term +/-0.040 % per channel (68 dB, typ or min not stated); offset drift 4 uV/K.")
    A("- 25 ppm/K for every divider part (the 100k and 249 types are 10 ppm/K, the 953 and 330k 25 ppm/K).")
    open(os.path.join(HERE, "report.md"), "w").write("\n".join(L) + "\n")
